<?php
declare(strict_types=1); namespace Tests\Feature\Classrooms;
use App\Models\{AcademicYear,Classroom,GradeLevel}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ClassroomModelTest extends TestCase {use RefreshDatabase; public function test_display_name_is_computed_and_codes_are_unique_per_year_and_grade():void{$year=AcademicYear::create(['name'=>'2026/2027','starts_at'=>'2026-07-01','ends_at'=>'2027-06-30','is_active'=>true]);$grade=GradeLevel::create(['number'=>2,'name'=>'Kelas 2','roman_label'=>'II','sort_order'=>2]);$room=Classroom::create(['academic_year_id'=>$year->id,'grade_level_id'=>$grade->id,'code'=>'II A','name'=>"AL-MU'MIN",'is_active'=>true]);$this->assertSame("Kelas 2 - II A (AL-MU'MIN)",$room->display_name);$this->expectException(\Illuminate\Database\QueryException::class);Classroom::create(['academic_year_id'=>$year->id,'grade_level_id'=>$grade->id,'code'=>'II A']);} public function test_there_is_no_delete_route():void{$this->assertFalse(collect(app('router')->getRoutes())->contains(fn($r)=>$r->getName()==='classrooms.destroy'));}}
